#include <stdio.h>
#include <utility>
using namespace std;

#define punct pair<int,int>
#define ff first
#define ss second

const int dx[] = {-2, -2, -1, 1, 2, 2, 1, -1};
const int dy[] = {-1, 1, 2, 2, 1, -1, -2, -2};

int tl, tc, cl, cc, nr;
punct v[8];

int main()
{
    char c;
    int i, j, cate;
    bool ok;

    scanf("%c", &c);
    tl = c - 96;
    scanf("%c", &c);
    tc = c - '0';

    do {
        scanf("%c", &c);
        cl = c - 96;
    } while (c == 10);

    scanf("%c", &c);
    cc = c - '0';

    nr = 48;
    cate = 0;

    for (i = 0; i < 8; ++i)
        if (cl + dx[i] < 9 && cl + dx[i] > 0 &&
            cc + dy[i] < 9 && cc + dy[i] > 0 &&
            cl + dx[i] != tl && cc + dy[i] != tc) {
            nr--;
            v[i].ff = cl + dx[i];
            v[i].ss = cl + dx[i];
            cate++;
        }

    for (i = 0; i < 8; ++i)
        if (tl + dx[i] < 9 && tl + dx[i] > 0 &&
            tc + dy[i] < 9 && tc + dy[i] > 0 &&
            cl + dx[i] != tl && cc + dy[i] != tc) {
            ok = true;
            for (j = 0; j < cate; ++j)
                if (tl + dx[i] == v[j].ff && tc + dy[i] == v[j].ss)
                    ok = false;
            if (ok)
                nr--;
        }

    printf("%d", nr);
    return 0;
}

